# Merge every toolbox's *dir_locals fragment into one .dir-locals.el.
# Usage: merge_dir_locals <project-root> <dest>
root=$1
dest=$2

tmp=$(mktemp "$(dirname "$dest")/.dir-locals.el.XXXXXX")
trap 'rm -f "$tmp"' EXIT

{
  cat <<'HEADER'
;; Generated by emacs toolbox enterShell
;; Do not edit this file directly — it will be overwritten on shell entry.
HEADER
  if [ -d "$root/.toolboxes" ]; then
    # Emacs reads only the first form of .dir-locals.el, so splice
    # every fragment's ((MODE . VARS) ...) into one list. Repeated
    # MODE keys are fine: dir-locals applies every matching entry.
    first=1
    while IFS= read -r -d '' f; do
      if [ "$first" = 1 ]; then
        echo "("
        first=0
      fi
      sed -z 's/^[[:space:]]*(//; s/)[[:space:]]*$//' "$f"
      echo
    done < <(find "$root/.toolboxes" -type f -name '*dir_locals' -print0 | sort -z)
    [ "$first" = 1 ] || echo ")"
  fi
} >"$tmp"

if [ ! -f "$dest" ] || ! cmp -s "$tmp" "$dest"; then
  mv "$tmp" "$dest"
fi
